// Parse AI response and format for API
const aiResponse = $input.item.json.choices[0].message.content;
let parsed;

try {
  // Try to parse JSON
  parsed = JSON.parse(aiResponse);
} catch (e) {
  // If not JSON, create structure manually
  parsed = {
    title: "AI Generated Research Content",
    summary: aiResponse.substring(0, 200),
    content: aiResponse,
    keywords: [],
    references: [],
    relatedTopics: []
  };
}

// Get metadata from previous node
const metadata = $('Select Research Topic').item.json;

// Ensure all required fields
const researchContent = {
  id: metadata.id,
  date: metadata.date,
  title: parsed.title || metadata.topic,
  type: metadata.type,
  category: metadata.category,
  summary: parsed.summary || parsed.content?.substring(0, 200) || "Research content about " + metadata.topic,
  content: parsed.content || aiResponse,
  keywords: parsed.keywords || [metadata.topic, metadata.category],
  references: parsed.references || [
    {
      title: "NASA.gov",
      url: "https://www.nasa.gov/",
      source: "NASA",
      type: "website"
    }
  ],
  formulas: parsed.formulas || [],
  dataPoints: parsed.dataPoints || [],
  relatedTopics: parsed.relatedTopics || [],
  seoKeywords: parsed.seoKeywords || `${metadata.topic} ${metadata.category} research`
};

return { json: researchContent };
